def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    entries = []
    weight = 0.0
    for e, x in (s.get('composition') or {}).items():
        a = p.get(e) or {}
        ie = a.get('first_ionization_energy_eV')
        ea = a.get('electron_affinity_eV')
        if x is not None and x > 0 and ie is not None and ea is not None:
            hardness = max(ie - ea, 0.5)
            chi = 0.5 * (ie + ea)
            entries.append((x / hardness, chi))
            weight += x
    susceptibility = sum(w for w, chi in entries)
    if weight <= 0 or susceptibility <= 0:
        return 0.0
    mean = sum(w * chi for w, chi in entries) / susceptibility
    return sum(w * (chi - mean) ** 2 for w, chi in entries) / weight
